async function u(i=1){const n=`${window.APP_CONFIG?.baseUrl||"/"}api/regions?country_id=${i}`;try{const r=await(await fetch(n)).json();return r.success?r.data.map(o=>({id:o.id,name:o.region})):[]}catch(e){return console.error("Fetch Regions Error:",e),[]}}function g(i){const t=document.getElementById(i);if(!t)return;const n=t.querySelector('select[name="countryId"]'),e=t.querySelector('select[name="regionId"]');!n||!e||n.addEventListener("change",async r=>{const o=n.value,a=r.detail?.preSelectedRegionId;if(!o){e.innerHTML='<option value="">Select Region</option>';return}e.innerHTML='<option value="">Loading...</option>',e.disabled=!0;try{const l=(await u(o)).map(c=>{const d=a&&String(c.id)===String(a);return`<option value="${c.id}" ${d?"selected":""}>${c.name}</option>`}).join("");e.innerHTML=`
                <option value="">Select Region</option>
                ${l}
            `}catch(s){console.error("Failed to reload regions:",s),e.innerHTML='<option value="">Error loading regions</option>'}finally{e.disabled=!1}})}export{g as e,u as f};
